export type CostRow = { setup: string; costUsd: number | null };

export type CostStats = {
  setup: string;
  n: number;
  nullCount: number;
  totalUsd: number;
  meanUsd: number | null;
  p50Usd: number | null;
  p90Usd: number | null;
};

const round4 = (x: number): number => Math.round(x * 1e4) / 1e4;

// Nearest-rank percentile on an ascending-sorted, non-empty array.
function nearestRank(sorted: number[], p: number): number {
  const rank = Math.max(1, Math.ceil(p * sorted.length));
  return sorted[rank - 1];
}

/** Per-setup cost totals and spread. `n` counts non-null costs; nulls go to `nullCount`. */
export function costStats(rows: CostRow[]): CostStats[] {
  const bySetup = new Map<string, { values: number[]; nullCount: number }>();
  for (const r of rows) {
    let g = bySetup.get(r.setup);
    if (!g) bySetup.set(r.setup, (g = { values: [], nullCount: 0 }));
    if (r.costUsd === null || !Number.isFinite(r.costUsd)) g.nullCount++;
    else g.values.push(r.costUsd);
  }
  return [...bySetup.keys()]
    .sort((a, b) => (a < b ? -1 : a > b ? 1 : 0))
    .map((setup) => {
      const { values, nullCount } = bySetup.get(setup)!;
      const sorted = [...values].sort((a, b) => a - b);
      const total = sorted.reduce((s, v) => s + v, 0);
      const n = sorted.length;
      return {
        setup,
        n,
        nullCount,
        totalUsd: round4(total),
        meanUsd: n ? round4(total / n) : null,
        p50Usd: n ? round4(nearestRank(sorted, 0.5)) : null,
        p90Usd: n ? round4(nearestRank(sorted, 0.9)) : null,
      };
    });
}
EOF
cat > tests/costs.test.ts <<'EOF'
import { expect, test } from "bun:test";
import { costStats } from "../src/report/costs";

test("empty input", () => {
  expect(costStats([])).toEqual([]);
});

test("nulls excluded from stats, counted in nullCount; sorted by setup", () => {
  const rows = [
    { setup: "b", costUsd: 1 },
    { setup: "a", costUsd: 0.1 },
    { setup: "a", costUsd: null },
    { setup: "a", costUsd: 0.3 },
    { setup: "a", costUsd: 0.2 },
  ];
  expect(costStats(rows)).toEqual([
    { setup: "a", n: 3, nullCount: 1, totalUsd: 0.6, meanUsd: 0.2, p50Usd: 0.2, p90Usd: 0.3 },
    { setup: "b", n: 1, nullCount: 0, totalUsd: 1, meanUsd: 1, p50Usd: 1, p90Usd: 1 },
  ]);
});

test("nearest-rank percentiles on 10 values", () => {
  const rows = Array.from({ length: 10 }, (_, i) => ({ setup: "s", costUsd: 10 - i }));
  const [s] = costStats(rows);
  expect(s.p50Usd).toBe(5);
  expect(s.p90Usd).toBe(9);
  expect(s.meanUsd).toBe(5.5);
});

test("all-null setup", () => {
  expect(costStats([{ setup: "x", costUsd: null }])).toEqual([
    { setup: "x", n: 0, nullCount: 1, totalUsd: 0, meanUsd: null, p50Usd: null, p90Usd: null },
  ]);
});

test("rounds money to 4 decimals", () => {
  const [s] = costStats([
    { setup: "s", costUsd: 0.123456 },
    { setup: "s", costUsd: 0.000049 },
  ]);
  expect(s.totalUsd).toBe(0.1235);
  expect(s.meanUsd).toBe(0.0617);
  expect(s.p50Usd).toBe(0);
  expect(s.p90Usd).toBe(0.1235);
});
EOF
